export function initFamily(c){const {$,state,table,req,element,button,busy,toast}=c;const action=(a,p={})=>req('/rest/v1/rpc/family_action',{method:'POST',body:{action:a,payload:p}});let options=[];
 document.addEventListener('family:tenant-selected',()=>loadOptions().catch(()=>{}));
 async function loadOptions(){options=state.user?await table('kinship_options','select=*&order=generation,label'):await req('/rest/v1/rpc/tenant_kinship',{method:'POST',auth:false,body:{code:JSON.parse(localStorage.getItem('family-selection')||'null')?.code||'01'}});options=options.map(o=>({...o,enabled:o.enabled??true,for_reference:o.for_reference??true}));for(const prefix of ['signup','profile']){const select=$(prefix+'-relation'),value=select.value;select.replaceChildren(element('option','اختر…'));select.firstChild.value='';for(const o of options.filter(o=>o.enabled&&o.for_reference||o.code===value)){const item=element('option',o.label);item.value=o.code;select.append(item);}select.value=value;}}
 loadOptions().catch(()=>toast('تعذّر تحميل خيارات القرابة. حاول تحديث الصفحة.'));
 for(const prefix of ['signup','profile']){const input=$(prefix+'-ref'),box=element('div',undefined,'reference-results');input.after(box);input.placeholder='الاسم أو بداية رقم الجوال';let timer,version=0;input.addEventListener('input',()=>{clearTimeout(timer);const n=++version;timer=setTimeout(async()=>{box.replaceChildren();if(!input.value.trim())return;if(!state.user){box.append(element('small','يمكن البحث عن المعرّف من حسابك بعد تأكيد البريد. أدخل اسمه الرباعي الآن.'));return;}try{const rows=await action('referees',{term:input.value.trim()});if(n!==version)return;for(const p of rows)box.append(button(p.display_name,()=>{input.value=p.display_name;box.replaceChildren();},'chat-contact'));if(!rows.length)box.append(element('small','لا توجد أسماء مطابقة.'));}catch(e){box.textContent=e.message;}},180);});}
 const open=button('♧ شجرة عائلتي والأسماء المشابهة',tree,'secondary');open.id='family-tree-open';$('profile-dialog').append(open);
 function dialog(title){const d=element('dialog');d.className='family-dialog';d.append(element('h2',title),button('✕ إغلاق',()=>{d.close();d.remove();},'dialog-close text-button'));document.body.append(d);d.showModal();return d;}
 async function tree(){if(state.profile.status!=='active')throw new Error('شجرة العائلة للأعضاء المعتمدين.');await loadOptions();const d=dialog('شجرة عائلتي');d.append(element('p','القرابة حسب تأكيدك الشخصي. تشابه الاسم اقتراح ولا يثبت النسب. الترتيب بحسب جيل الأقارب بالنسبة لك.','muted'));const chart=element('div',undefined,'family-tree'),suggest=element('div');d.append(chart,element('h3','أسماء مشابهة — 70٪ أو أكثر'),element('p','متوسط التشابه الإملائي في اسم الأب والجد والعائلة؛ الاسم الأول لا يدخل في النسبة.','muted'),suggest);await render();const rows=await action('similar');for(const p of rows){const row=element('div',undefined,'activity-row');row.append(element('strong',p.display_name),element('small',' · '+p.score+'٪'));const select=element('select');select.setAttribute('aria-label','صلة قرابة '+p.display_name);select.append(element('option','حدد صلة القرابة'));select.firstChild.value='';for(const o of options.filter(o=>o.enabled)){const item=element('option',o.label);item.value=o.code;select.append(item);}row.append(select,button('تأكيد وإضافة إلى شجرتي',async()=>{if(!select.value)throw new Error('اختر صلة القرابة أولًا.');await action('link',{member:p.id,relation:select.value});await render();toast('أضيف العضو إلى شجرتك.');},'secondary'));suggest.append(row);}if(!rows.length)suggest.append(element('p','لا توجد أسماء ضمن نسبة التشابه حاليًا.'));async function render(){const links=await action('tree');chart.replaceChildren();const levels=[...new Set([0,...links.map(r=>r.generation)])].sort((a,b)=>a-b);for(const level of levels){const band=element('section',undefined,'tree-level');band.append(element('small',level<0?'الجيل الأعلى '+Math.abs(level):level>0?'الجيل التالي '+level:'جيلي'));const nodes=element('div',undefined,'tree-nodes');if(level===0)nodes.append(element('div',state.profile.display_name+' (أنا)','tree-person self'));for(const p of links.filter(p=>p.generation===level)){const node=element('div',undefined,'tree-person');node.append(element('strong',p.display_name),element('small',p.label),button('إزالة',async()=>{await action('unlink',{member:p.id});await render();}));nodes.append(node);}band.append(nodes);chart.append(band);}}}
 const form=element('form');form.id='kinship-admin';form.innerHTML='<h3>خيارات صلة القرابة</h3><p class="muted">تحدد الجيل بالنسبة للمستخدم: الأب −1، الجد −2، الأخ أو الزوج 0، الابن 1. تعطيل الخيار يمنع اختياره الجديد ويحافظ على القرابات السابقة.</p><label>اسم صلة القرابة<input name="label" required maxlength="60"></label><label>ترتيب الجيل<input name="generation" type="number" min="-4" max="4" value="0" required></label><label class="inline"><input name="reference" type="checkbox"> متاح لاختيار المعرّف للأنثى</label><button class="secondary">إضافة خيار قرابة</button><div id="kinship-list"></div>';const adminList=$('kinship-list')||form.querySelector('#kinship-list');adminList.remove();$('settings-section').append(form,adminList);form.onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await table('kinship_options','',{method:'POST',body:{code:'relation_'+crypto.randomUUID().replaceAll('-','').slice(0,20),label:form.elements.label.value.trim(),generation:Number(form.elements.generation.value),for_reference:form.elements.reference.checked}});form.reset();await admin();toast('تمت إضافة خيار القرابة.');});};
 async function admin(){await loadOptions();const list=$('kinship-list');list.replaceChildren();for(const o of options){const f=element('form',undefined,'activity-row'),name=element('input'),generation=element('input'),ref=element('input'),enabled=element('input');name.value=o.label;name.required=true;name.maxLength=60;name.setAttribute('aria-label','اسم القرابة');generation.type='number';generation.min=-4;generation.max=4;generation.required=true;generation.value=o.generation;generation.setAttribute('aria-label','ترتيب الجيل');ref.type=enabled.type='checkbox';ref.checked=o.for_reference;enabled.checked=o.enabled;const a=element('label','متاح للمُعرّف','inline'),b=element('label','مفعّل','inline');a.append(ref);b.append(enabled);const save=element('button','حفظ','secondary');f.append(name,generation,a,b,save);f.onsubmit=e=>{e.preventDefault();e.stopPropagation();busy(save,async()=>{await table('kinship_options','code=eq.'+o.code,{method:'PATCH',body:{label:name.value.trim(),generation:Number(generation.value),for_reference:ref.checked,enabled:enabled.checked}});await admin();toast('تم تحديث خيار القرابة.');});};list.append(f);}}
 return {admin,loadOptions};
}
